import os
import re
from typing import Any, Dict, List, Optional

import requests


class PerspectiveSafety:
    API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    DEFAULT_ATTRIBUTES = {
        "TOXICITY": {},
        "SEVERE_TOXICITY": {},
        "INSULT": {},
        "PROFANITY": {},
        "THREAT": {},
        "IDENTITY_ATTACK": {},
    }

    def __init__(
        self,
        api_key: Optional[str] = None,
        attributes: Optional[Dict[str, Dict[str, Any]]] = None,
        sentence_threshold: float = 0.75,
        token_threshold: float = 0.85,
        timeout: int = 30,
    ) -> None:
        self.api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("Missing Perspective API key. Set PERSPECTIVE_API_KEY.")
        self.attributes = attributes or self.DEFAULT_ATTRIBUTES
        self.sentence_threshold = sentence_threshold
        self.token_threshold = token_threshold
        self.timeout = timeout

    def analyze_text(self, text: str, language: Optional[str] = None) -> Dict[str, Any]:
        body: Dict[str, Any] = {
            "comment": {"text": text},
            "requestedAttributes": self.attributes,
            "doNotStore": True,
            "spanAnnotations": True,
        }
        if language:
            body["languages"] = [language]

        response = requests.post(
            f"{self.API_URL}?key={self.api_key}",
            json=body,
            timeout=self.timeout,
        )
        response.raise_for_status()
        return response.json()

    def flag_or_redact(
        self,
        text: str,
        language: Optional[str] = None,
        redact: bool = True,
        redaction_char: str = "█",
    ) -> Dict[str, Any]:
        analysis = self.analyze_text(text, language=language)
        flagged_spans = self._extract_flagged_spans(analysis, text)
        merged_spans = self._merge_spans(flagged_spans)

        result = {
            "provider": "Perspective API",
            "text": text,
            "flagged": bool(merged_spans),
            "spans": merged_spans,
            "attribute_scores": self._extract_summary_scores(analysis),
            "redacted_text": self._redact_text(text, merged_spans, redaction_char) if redact else text,
            "raw_response": analysis,
        }
        return result

    def _extract_summary_scores(self, analysis: Dict[str, Any]) -> Dict[str, float]:
        out: Dict[str, float] = {}
        attr_scores = analysis.get("attributeScores", {})
        for attr, payload in attr_scores.items():
            score = (
                payload.get("summaryScore", {})
                .get("value")
            )
            if isinstance(score, (int, float)):
                out[attr] = float(score)
        return out

    def _extract_flagged_spans(self, analysis: Dict[str, Any], text: str) -> List[Dict[str, Any]]:
        spans: List[Dict[str, Any]] = []
        attr_scores = analysis.get("attributeScores", {})

        for attr, payload in attr_scores.items():
            for ann in payload.get("spanScores", []) or []:
                begin = ann.get("begin")
                end = ann.get("end")
                score = ann.get("score", {}).get("value")
                if not isinstance(begin, int) or not isinstance(end, int):
                    continue
                if not isinstance(score, (int, float)):
                    continue
                if score < self.token_threshold:
                    continue
                if begin < 0 or end > len(text) or begin >= end:
                    continue
                spans.append(
                    {
                        "start": begin,
                        "end": end,
                        "label": attr,
                        "score": float(score),
                        "text": text[begin:end],
                    }
                )

        if spans:
            return spans

        sentences = self._sentence_spans(text)
        summary_scores = self._extract_summary_scores(analysis)
        triggered_attrs = [
            {"label": k, "score": v}
            for k, v in summary_scores.items()
            if v >= self.sentence_threshold
        ]
        if not triggered_attrs:
            return []

        for sent in sentences:
            for attr in triggered_attrs:
                spans.append(
                    {
                        "start": sent["start"],
                        "end": sent["end"],
                        "label": attr["label"],
                        "score": attr["score"],
                        "text": text[sent["start"]:sent["end"]],
                    }
                )
        return spans

    def _sentence_spans(self, text: str) -> List[Dict[str, int]]:
        matches = list(re.finditer(r"[^.!?\n]+[.!?\n]*", text))
        spans: List[Dict[str, int]] = []
        for m in matches:
            start, end = m.span()
            if start == end:
                continue
            spans.append({"start": start, "end": end})
        if not spans and text:
            spans.append({"start": 0, "end": len(text)})
        return spans

    def _merge_spans(self, spans: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not spans:
            return []

        normalized = sorted(spans, key=lambda s: (s["start"], s["end"]))
        merged: List[Dict[str, Any]] = []

        for span in normalized:
            if not merged or span["start"] > merged[-1]["end"]:
                merged.append(
                    {
                        "start": span["start"],
                        "end": span["end"],
                        "labels": [span["label"]],
                        "score": span["score"],
                        "text": span["text"],
                    }
                )
            else:
                merged[-1]["end"] = max(merged[-1]["end"], span["end"])
                merged[-1]["labels"] = sorted(set(merged[-1]["labels"] + [span["label"]]))
                merged[-1]["score"] = max(merged[-1]["score"], span["score"])

        return merged

    def _redact_text(self, text: str, spans: List[Dict[str, Any]], redaction_char: str) -> str:
        if not spans:
            return text

        chars = list(text)
        for span in spans:
            for i in range(span["start"], span["end"]):
                if not chars[i].isspace():
                    chars[i] = redaction_char
        return "".join(chars)


def moderate_text(
    text: str,
    language: Optional[str] = None,
    redact: bool = True,
    sentence_threshold: float = 0.75,
    token_threshold: float = 0.85,
) -> Dict[str, Any]:
    client = PerspectiveSafety(
        sentence_threshold=sentence_threshold,
        token_threshold=token_threshold,
    )
    return client.flag_or_redact(text=text, language=language, redact=redact)
